#!/usr/bin/env python3
"""
Automatisk generert av generate.py (tournament) - IKKE rediger denne filen direkte.

Turneringsfunksjon: admin-utstedt kode lar en spiller booke en enkelttime uten
betaling (skriver inn motstander i stedet), vises blatt med motstander for admin,
egen 'Turnering'-fane i adminpanelet.

Legger OGSA igjen en ny fil, supabase/migrations/0006_add_tournament_fields.sql
- den kjores IKKE av dette skriptet (det er bare SQL), men MA limes inn og
kjores i Supabase sitt SQL Editor separat, se utskriften til slutt.

Idempotent: hvert steg hopper over seg selv hvis allerede gjort.
Kjor fra prosjektroten: python3 scripts/deploy_tournament.py
"""
import pathlib
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent

ok = True

def apply_edit(path, old, new, marker, label):
    global ok
    text = path.read_text()
    if marker in text:
        print(f"[already done] {label}")
        return
    if text.count(old) != 1:
        print(f"[SKIPPED - ikke funnet/entydig] {label}")
        ok = False
        return
    path.write_text(text.replace(old, new, 1))
    print(f"[OK] {label}")

def write_full(path, content, marker, label):
    global ok
    if path.exists() and marker in path.read_text():
        print(f"[already done] {label}")
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)
    print(f"[OK] {label}")

