write_full(ROOT / 'supabase' / 'migrations' / '0006_add_tournament_fields.sql', '-- Turneringsfunksjon: en spiller kan booke en enkelttime med en admin-utstedt\n-- kode (se lib/settings/tournament.ts) i stedet for å betale - da skriver de\n-- inn hvem de møter i stedet for telefonnummer. Lagret direkte på\n-- booking_groups (samme sted som customer_name/customer_phone), siden det\n-- er ett ekstra, valgfritt felt på bookingen - ikke en egen tabell.\nalter table booking_groups add column if not exists opponent_name text;\n', 'opponent_name text', 'ny fil: supabase/migrations/0006_add_tournament_fields.sql')
write_full(ROOT / 'lib' / 'settings' / 'tournament.ts', 'import "server-only";\nimport { getRepository } from "@/lib/db";\nimport { isValidDateString } from "./openingHours";\nimport { todayInClubTimeZone } from "@/lib/slots";\n\n/**\n * Turneringsfunksjon: admin setter ÉN delt kode som spillere kan skrive inn\n * når de booker en enkelttime på den offentlige bookingsiden (se\n * app/BookingCalendar.tsx) – da hopper de over betaling, og skriver i stedet\n * inn hvem de møter ("motstander", se opponentName i lib/db/types.ts) i\n * stedet for telefonnummer. Koden gjelder KUN enkelttimer, ikke gjentakende\n * bookinger (se håndhevingen i app/api/squash/bookings/route.ts).\n *\n * Lagret som tre separate nøkler i den samme generiske nøkkel/verdi-\n * innstillingstabellen som resten av innstillingene (se lib/settings/pricing.ts\n * for samme mønster med flere uavhengige nøkler) – ETT sett med innstillinger\n * for HELE turneringen (ikke én kode per kamp), per admins eget valg.\n */\nconst CODE_KEY = "tournamentCode";\nconst ACTIVE_KEY = "tournamentActive";\nconst EXPIRES_KEY = "tournamentExpiresAt";\n\nexport interface TournamentSettings {\n  /** Den delte koden spillere skriver inn – tom streng betyr at ingen kode er satt ennå. */\n  code: string;\n  /** Av/på-bryteren – koden godtas KUN når denne er true, uavhengig av om expiresAt også tillater det. */\n  active: boolean;\n  /** Siste dato ("YYYY-MM-DD") koden kan brukes, eller null for ingen utløpsdato. */\n  expiresAt: string | null;\n}\n\nexport async function getTournamentSettings(): Promise<TournamentSettings> {\n  const repo = await getRepository();\n  const [code, activeRaw, expiresAt] = await Promise.all([\n    repo.getSetting(CODE_KEY),\n    repo.getSetting(ACTIVE_KEY),\n    repo.getSetting(EXPIRES_KEY),\n  ]);\n\n  return {\n    code: code ?? "",\n    active: activeRaw === "true",\n    expiresAt: expiresAt && isValidDateString(expiresAt) ? expiresAt : null,\n  };\n}\n\n/** Kaster med en norsk feilmelding ved en ugyldig utløpsdato, eller hvis koden skrus på uten at noen kode er satt. */\nexport async function saveTournamentSettings(input: TournamentSettings): Promise<TournamentSettings> {\n  const code = input.code.trim();\n  if (input.active && !code) {\n    throw new Error("Skriv inn en kode før turneringen kan skrus på.");\n  }\n  if (input.expiresAt !== null && !isValidDateString(input.expiresAt)) {\n    throw new Error("Ugyldig utløpsdato (forventet format ÅÅÅÅ-MM-DD).");\n  }\n\n  const repo = await getRepository();\n  await Promise.all([\n    repo.setSetting(CODE_KEY, code),\n    repo.setSetting(ACTIVE_KEY, input.active ? "true" : "false"),\n    repo.setSetting(EXPIRES_KEY, input.expiresAt ?? ""),\n  ]);\n\n  return { code, active: input.active, expiresAt: input.expiresAt };\n}\n\n/**\n * Den faktiske sjekken brukt BÅDE av den offentlige "er denne koden gyldig\n * akkurat nå"-sjekken (se app/api/squash/tournament-code/route.ts, kalt mens\n * kunden skriver) OG av selve bookingen (se app/api/squash/bookings/route.ts,\n * sjekket på nytt server-side – aldri stol på klientens egen "gyldig kode"-\n * sjekk alene). Sammenligner uten hensyn til store/små bokstaver eller\n * ekstra mellomrom, siden en spiller lett kan skrive koden litt annerledes\n * enn admin gjorde.\n */\nexport async function isTournamentCodeValid(inputCode: string): Promise<boolean> {\n  const trimmed = inputCode.trim();\n  if (!trimmed) return false;\n\n  const settings = await getTournamentSettings();\n  if (!settings.active || !settings.code) return false;\n  if (trimmed.toLowerCase() !== settings.code.trim().toLowerCase()) return false;\n  if (settings.expiresAt && todayInClubTimeZone() > settings.expiresAt) return false;\n\n  return true;\n}\n', 'export async function isTournamentCodeValid', 'ny fil: lib/settings/tournament.ts')
write_full(ROOT / 'app' / 'api' / 'admin' / 'settings' / 'tournament' / 'route.ts', 'import { NextRequest, NextResponse } from "next/server";\nimport { getTournamentSettings, saveTournamentSettings, type TournamentSettings } from "@/lib/settings/tournament";\n\nexport const dynamic = "force-dynamic";\n\n/**\n * GET  /api/admin/settings/tournament – hent dagens turneringsinnstillinger\n *      (kode, av/på, utløpsdato).\n * POST /api/admin/settings/tournament – lagre alle tre på nytt (sendes\n *      alltid samlet fra adminpanelets skjema, se TournamentManager.tsx).\n *\n * Beskyttet av middleware.ts – IKKE i noen av BOOKINGS_ONLY_ALLOWED_*-listene\n * der, så en begrenset ("bookings_only") administrator nektes automatisk,\n * akkurat som resten av Oppsett/Vipps/Utseende.\n */\nexport async function GET() {\n  try {\n    const settings = await getTournamentSettings();\n    return NextResponse.json(settings);\n  } catch (err) {\n    return NextResponse.json(\n      { error: err instanceof Error ? err.message : "Kunne ikke hente turneringsinnstillinger." },\n      { status: 500 }\n    );\n  }\n}\n\ninterface SaveBody {\n  code?: string;\n  active?: boolean;\n  expiresAt?: string | null;\n}\n\nexport async function POST(request: NextRequest) {\n  let body: SaveBody;\n  try {\n    body = (await request.json()) as SaveBody;\n  } catch {\n    return NextResponse.json({ error: "Ugyldig forespørsel." }, { status: 400 });\n  }\n\n  try {\n    const input: TournamentSettings = {\n      code: typeof body.code === "string" ? body.code : "",\n      active: body.active === true,\n      expiresAt: body.expiresAt ? body.expiresAt : null,\n    };\n    const saved = await saveTournamentSettings(input);\n    return NextResponse.json({ ok: true, ...saved });\n  } catch (err) {\n    return NextResponse.json({ error: err instanceof Error ? err.message : "Kunne ikke lagre." }, { status: 400 });\n  }\n}\n', 'getTournamentSettings, saveTournamentSettings', 'ny fil: app/api/admin/settings/tournament/route.ts')
write_full(ROOT / 'app' / 'api' / 'squash' / 'tournament-code' / 'route.ts', 'import { NextRequest, NextResponse } from "next/server";\nimport { isTournamentCodeValid } from "@/lib/settings/tournament";\n\nexport const dynamic = "force-dynamic";\n\n/**\n * GET /api/squash/tournament-code?code=...\n *\n * Offentlig (ingen innlogging kreves) – lar bookingsiden sjekke om en\n * turneringskode kunden skriver inn er gyldig AKKURAT NÅ, mens de fortsatt\n * fyller ut skjemaet (se app/BookingCalendar.tsx). Svarer KUN med\n * true/false – aldri noe om selve koden, om turneringen er av/på, eller\n * utløpsdatoen, slik at noen som prøver seg frem ikke lærer noe nyttig av\n * svaret. Selve bookingen (se app/api/squash/bookings/route.ts) validerer\n * uansett koden PÅ NYTT server-side – denne ruten er bare for å gi kunden\n * rask tilbakemelding mens de skriver.\n */\nexport async function GET(request: NextRequest) {\n  const code = request.nextUrl.searchParams.get("code") ?? "";\n  if (!code.trim()) return NextResponse.json({ valid: false });\n\n  try {\n    const valid = await isTournamentCodeValid(code);\n    return NextResponse.json({ valid });\n  } catch (err) {\n    console.error("[tournament-code] feil ved sjekk av kode:", err);\n    return NextResponse.json({ valid: false });\n  }\n}\n', 'GET /api/squash/tournament-code', 'ny fil: app/api/squash/tournament-code/route.ts')
write_full(ROOT / 'app' / 'admin' / 'turnering' / 'page.tsx', 'import TournamentManager from "./TournamentManager";\n\nexport const metadata = { title: "Turnering – Squashbooking admin" };\n\nexport default function AdminTournamentPage() {\n  return <TournamentManager />;\n}\n', 'AdminTournamentPage', 'ny fil: app/admin/turnering/page.tsx')
write_full(ROOT / 'app' / 'admin' / 'turnering' / 'TournamentManager.tsx', '"use client";\n\nimport { useEffect, useState, type FormEvent } from "react";\nimport styles from "../admin.module.css";\nimport { formatOslo } from "@/lib/formatting";\nimport AdminNav from "../AdminNav";\n\ninterface TournamentSettingsResponse {\n  code: string;\n  active: boolean;\n  expiresAt: string | null;\n}\n\ninterface SlotInfo {\n  startTime: string;\n  endTime: string;\n}\n\ntype MatchStatus = "pending" | "confirmed" | "cancelled" | "expired";\n\ninterface TournamentMatch {\n  id: string;\n  status: MatchStatus;\n  customerName: string;\n  opponentName: string | null;\n  slots: SlotInfo[];\n}\n\nconst STATUS_LABEL: Record<MatchStatus, string> = {\n  pending: "Venter",\n  confirmed: "Bekreftet",\n  cancelled: "Avlyst",\n  expired: "Utløpt",\n};\n\n/**\n * "Turnering" – egen fane (kun full administrator, se AdminNav.tsx og\n * middleware.ts) der admin setter opp den delte turneringskoden (se\n * lib/settings/tournament.ts) og ser kampene som er booket med den.\n */\nexport default function TournamentManager() {\n  const [code, setCode] = useState("");\n  const [active, setActive] = useState(false);\n  const [expiresAt, setExpiresAt] = useState("");\n  const [loadingSettings, setLoadingSettings] = useState(true);\n  const [savingSettings, setSavingSettings] = useState(false);\n  const [saveMessage, setSaveMessage] = useState<{ ok: boolean; text: string } | null>(null);\n\n  const [matches, setMatches] = useState<TournamentMatch[]>([]);\n  const [loadingMatches, setLoadingMatches] = useState(true);\n  const [cancellingId, setCancellingId] = useState<string | null>(null);\n\n  async function loadSettings() {\n    setLoadingSettings(true);\n    try {\n      const res = await fetch("/api/admin/settings/tournament", { cache: "no-store" });\n      const data = (await res.json()) as TournamentSettingsResponse;\n      setCode(data.code ?? "");\n      setActive(!!data.active);\n      setExpiresAt(data.expiresAt ?? "");\n    } finally {\n      setLoadingSettings(false);\n    }\n  }\n\n  async function loadMatches() {\n    setLoadingMatches(true);\n    try {\n      const res = await fetch("/api/admin/bookings", { cache: "no-store" });\n      const data = (await res.json()) as { bookings: TournamentMatch[] };\n      // Adminpanelets vanlige "alle bookinger"-endepunkt (se\n      // app/api/admin/bookings/route.ts) – en turneringskamp er bare en\n      // enkeltbooking som i tillegg har opponentName satt (se\n      // lib/db/types.ts), så vi filtrerer på det her i stedet for å ha et\n      // eget endepunkt kun for dette.\n      setMatches((data.bookings ?? []).filter((b) => !!b.opponentName));\n    } finally {\n      setLoadingMatches(false);\n    }\n  }\n\n  useEffect(() => {\n    loadSettings();\n    loadMatches();\n  }, []);\n\n  async function handleSaveSettings(e: FormEvent) {\n    e.preventDefault();\n    setSavingSettings(true);\n    setSaveMessage(null);\n    try {\n      const res = await fetch("/api/admin/settings/tournament", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ code, active, expiresAt: expiresAt || null }),\n      });\n      const data = (await res.json()) as { error?: string };\n      if (!res.ok) {\n        setSaveMessage({ ok: false, text: data.error ?? "Kunne ikke lagre." });\n        return;\n      }\n      setSaveMessage({ ok: true, text: "Lagret." });\n    } catch {\n      setSaveMessage({ ok: false, text: "Kunne ikke lagre akkurat nå." });\n    } finally {\n      setSavingSettings(false);\n    }\n  }\n\n  async function handleCancelMatch(match: TournamentMatch) {\n    const label = `${match.customerName} vs ${match.opponentName}`;\n    if (!window.confirm(`Avlyse "${label}"? Dette kan ikke angres.`)) return;\n\n    setCancellingId(match.id);\n    try {\n      const res = await fetch(`/api/admin/bookings/${match.id}`, { method: "DELETE" });\n      const data = (await res.json().catch(() => ({}))) as { error?: string };\n      if (!res.ok) window.alert(data.error ?? "Kunne ikke avlyse kampen.");\n      await loadMatches();\n    } finally {\n      setCancellingId(null);\n    }\n  }\n\n  return (\n    <>\n      <AdminNav active="turnering" />\n      <main className={styles.page}>\n        <div className={styles.tabPanel}>\n          <h1 className={styles.title}>Turnering</h1>\n          <p className={styles.subtitle}>\n            Spillere som skriver inn koden under når de booker en enkelttime, slipper å betale – de skriver i stedet\n            inn hvem de møter. Bookingen vises som vanlig opptatt for alle andre, men blått og med motstander for deg\n            her i adminpanelet.\n          </p>\n\n          <div className={styles.card}>\n            <h2 style={{ marginTop: 0, fontSize: "1.1rem" }}>Turneringskode</h2>\n            {loadingSettings ? (\n              <p>Laster …</p>\n            ) : (\n              <form onSubmit={handleSaveSettings} className={styles.form}>\n                <div className={styles.formRow}>\n                  <label htmlFor="tournament-settings-code">Kode spillerne skriver inn</label>\n                  <input\n                    id="tournament-settings-code"\n                    type="text"\n                    maxLength={50}\n                    value={code}\n                    onChange={(e) => setCode(e.target.value)}\n                    placeholder="F.eks. HOST2026"\n                  />\n                </div>\n\n                <label className={styles.checkboxOption}>\n                  <input type="checkbox" checked={active} onChange={(e) => setActive(e.target.checked)} />\n                  Koden er aktiv (spillere kan bruke den nå)\n                </label>\n\n                <div className={styles.formRow}>\n                  <label htmlFor="tournament-settings-expires">Utløpsdato (valgfritt)</label>\n                  <input\n                    id="tournament-settings-expires"\n                    type="date"\n                    value={expiresAt}\n                    onChange={(e) => setExpiresAt(e.target.value)}\n                  />\n                  <p className={styles.bookingMeta}>La stå tom for ingen utløpsdato.</p>\n                </div>\n\n                {saveMessage && <p className={saveMessage.ok ? styles.success : styles.error}>{saveMessage.text}</p>}\n\n                <button type="submit" className={styles.submitButton} disabled={savingSettings}>\n                  {savingSettings ? "Lagrer …" : "Lagre"}\n                </button>\n              </form>\n            )}\n          </div>\n\n          <div className={styles.card}>\n            <h2 style={{ marginTop: 0, fontSize: "1.1rem" }}>Kamper i turneringen</h2>\n            {loadingMatches && <p>Laster …</p>}\n            {!loadingMatches && matches.length === 0 && (\n              <p className={styles.bookingMeta}>Ingen turneringskamper bestilt ennå.</p>\n            )}\n            {!loadingMatches && matches.length > 0 && (\n              <div className={styles.userList}>\n                {matches.map((m) => (\n                  <div key={m.id} className={styles.userRow}>\n                    <div>\n                      <strong>\n                        {m.customerName} vs {m.opponentName}\n                      </strong>\n                      <div className={styles.bookingMeta}>\n                        {m.slots.map((s) => formatOslo(s.startTime, "EEEE d. MMM yyyy \'kl.\' HH:mm")).join(", ")}\n                        {" · "}\n                        {STATUS_LABEL[m.status]}\n                      </div>\n                    </div>\n                    {(m.status === "pending" || m.status === "confirmed") && (\n                      <button\n                        type="button"\n                        className={styles.dangerButton}\n                        disabled={cancellingId === m.id}\n                        onClick={() => handleCancelMatch(m)}\n                      >\n                        {cancellingId === m.id ? "Avlyser …" : "Avlys"}\n                      </button>\n                    )}\n                  </div>\n                ))}\n              </div>\n            )}\n          </div>\n        </div>\n      </main>\n    </>\n  );\n}\n', 'export default function TournamentManager', 'ny fil: app/admin/turnering/TournamentManager.tsx')

